1	package strategy
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"os"
9		"os/exec"
10		"strings"
11		"sync"
12		"time"
13	
14		"github.com/entireio/cli/cmd/entire/cli/checkpoint"
15		"github.com/entireio/cli/cmd/entire/cli/settings"
16	
17		"github.com/go-git/go-git/v6"
18		"github.com/go-git/go-git/v6/plumbing"
19		"github.com/go-git/go-git/v6/plumbing/object"
20	)
21	
22	// pushBranchIfNeeded pushes a branch to the given target if it has unpushed changes.
23	// The target can be a remote name (e.g., "origin") or a URL for direct push.
24	// When pushing to a URL, the "has unpushed" optimization is skipped since there are
25	// no remote tracking refs — git itself handles the no-op case.
26	// Does not check any settings — callers are responsible for gating.
27	func pushBranchIfNeeded(ctx context.Context, target, branchName string) error {
28		repo, err := OpenRepository(ctx)
29		if err != nil {
30			return nil //nolint:nilerr // Hook must be silent on failure
31		}
32	
33		// Check if branch exists locally
34		branchRef := plumbing.NewBranchReferenceName(branchName)
35		localRef, err := repo.Reference(branchRef, true)
36		if err != nil {
37			// No branch, nothing to push
38			return nil //nolint:nilerr // Expected when no sessions exist yet
39		}
40	
41		// Only check remote tracking refs when target is a remote name (not a URL).
42		// URLs don't have tracking refs, so we always attempt the push and let git handle it.
43		if !isURL(target) && !hasUnpushedSessionsCommon(repo, target, localRef.Hash(), branchName) {
44			return nil
45		}
46	
47		return doPushBranch(ctx, target, branchName)
48	}
49	
50	// hasUnpushedSessionsCommon checks if the local branch differs from the remote.
51	// Returns true if there's any difference that needs syncing (local ahead, remote ahead, or diverged).
52	func hasUnpushedSessionsCommon(repo *git.Repository, remote string, localHash plumbing.Hash, branchName string) bool {
53		// Check for remote tracking ref: refs/remotes/<remote>/<branch>
54		remoteRefName := plumbing.NewRemoteReferenceName(remote, branchName)
55		remoteRef, err := repo.Reference(remoteRefName, true)
56		if err != nil {
57			// Remote branch doesn't exist yet - we have content to push
58			return true
59		}
60	
61		// If local and remote point to same commit, nothing to sync
62		// This is the only case where we skip - any difference needs handling
63		return localHash != remoteRef.Hash()
64	}
65	
66	// doPushBranch pushes the given branch to the target with fetch+merge recovery.
67	// The target can be a remote name or a URL.
68	func doPushBranch(ctx context.Context, target, branchName string) error {
69		displayTarget := target
70		if isURL(target) {
71			displayTarget = "checkpoint remote"
72		}
73	
74		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", branchName, displayTarget)
75		stop := startProgressDots(os.Stderr)
76	
77		// Try pushing first
78		if result, err := tryPushSessionsCommon(ctx, target, branchName); err == nil {
79			finishPush(ctx, stop, result, target)
80			return nil
81		}
82		stop("")
83	
84		// Push failed - likely non-fast-forward. Try to fetch and rebase.
85		fmt.Fprintf(os.Stderr, "[entire] Syncing %s with remote...", branchName)
86		stop = startProgressDots(os.Stderr)
87	
88		if err := fetchAndRebaseSessionsCommon(ctx, target, branchName); err != nil {
89			stop("")
90			fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't sync %s: %v\n", branchName, err)
91			printCheckpointRemoteHint(target)
92			return nil // Don't fail the main push
93		}
94		stop(" done")
95	
96		// Try pushing again after rebase
97		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", branchName, displayTarget)
98		stop = startProgressDots(os.Stderr)
99	
100		if result, err := tryPushSessionsCommon(ctx, target, branchName); err != nil {
101			stop("")
102			fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push %s after sync: %v\n", branchName, err)
103			printCheckpointRemoteHint(target)
104		} else {
105			finishPush(ctx, stop, result, target)
106		}
107	
108		return nil
109	}
110	
111	// printCheckpointRemoteHint prints a hint when a push to a checkpoint URL fails.
112	// Only prints when the target is a URL (not the user's default remote).
113	func printCheckpointRemoteHint(target string) {
114		if !isURL(target) {
115			return
116		}
117		fmt.Fprintln(os.Stderr, "[entire] A checkpoint remote is configured in Entire settings (.entire/settings.json or .entire/settings.local.json) but could not be reached.")
118		fmt.Fprintln(os.Stderr, "[entire] Checkpoints are saved locally but not synced. Ensure you have access to the checkpoint remote.")
119	}
120	
121	// settingsHintOnce ensures the settings commit hint prints at most once per process.
122	var settingsHintOnce sync.Once
123	
124	// checkpointsV2MigrationHintOnce ensures the checkpoints v2 migration hint prints at most once per process.
125	var checkpointsV2MigrationHintOnce sync.Once
126	
127	// printSettingsCommitHint prints a hint after a successful checkpoint remote push
128	// when the committed .entire/settings.json does not contain a checkpoint_remote config.
129	// entire.io discovers the external checkpoint repo by reading the committed project
130	// settings, so the checkpoint_remote must be present in HEAD:.entire/settings.json
131	// (not just in settings.local.json or uncommitted local changes).
132	// Uses sync.Once to avoid duplicates when multiple branches/refs are pushed in a
133	// single pre-push invocation.
134	func printSettingsCommitHint(ctx context.Context, target string) {
135		if !isURL(target) {
136			return
137		}
138		settingsHintOnce.Do(func() {
139			if isCheckpointRemoteCommitted(ctx) {
140				return
141			}
142			fmt.Fprintln(os.Stderr, "[entire] Note: Checkpoints were pushed to a separate checkpoint remote, but .entire/settings.json does not contain checkpoint_remote in the latest commit. entire.io will not be able to discover these checkpoints until checkpoint_remote is committed and pushed in .entire/settings.json.")
143		})
144	}
145	
146	// printCheckpointsV2MigrationHint prints a hint when the committed project
147	// settings enable checkpoints_version: 2 AND there are v1 checkpoints that have
148	// not yet been mirrored into v2. Suppressed when v2 already has every v1
149	// checkpoint (nothing to migrate) so the hint does not become noise once the
150	// migration is done.
151	func printCheckpointsV2MigrationHint(ctx context.Context) {
152		checkpointsV2MigrationHintOnce.Do(func() {
153			if !isCheckpointsVersion2Committed(ctx) {
154				return
155			}
156			if !hasUnmigratedV1Checkpoints(ctx) {
157				return
158			}
159			fmt.Fprintln(os.Stderr, "[entire] Note: .entire/settings.json sets checkpoints_version: 2. Run 'entire migrate --checkpoints v2' to migrate existing checkpoints to v2.")
160			fmt.Fprintln(os.Stderr, "[entire] Use 'entire migrate --checkpoints v2 --force' to rewrite all checkpoints in v2.")
161		})
162	}
163	
164	// hasUnmigratedV1Checkpoints reports whether any v1 checkpoint has no matching
165	// entry in v2. Any failure opening the repo or listing either store is treated
166	// as "no migration needed" so we stay silent instead of printing a speculative
167	// hint — the hint is advisory and should never be the reason a push gets noisy.
168	func hasUnmigratedV1Checkpoints(ctx context.Context) bool {
169		repo, err := OpenRepository(ctx)
170		if err != nil {
171			return false
172		}
173		v1List, err := checkpoint.NewGitStore(repo).ListCommitted(ctx)
174		if err != nil || len(v1List) == 0 {
175			return false
176		}
177		v2List, err := checkpoint.NewV2GitStore(repo, "").ListCommitted(ctx)
178		if err != nil {
179			return false
180		}
181		v2Set := make(map[string]struct{}, len(v2List))
182		for _, info := range v2List {
183			v2Set[info.CheckpointID.String()] = struct{}{}
184		}
185		for _, info := range v1List {
186			if _, ok := v2Set[info.CheckpointID.String()]; !ok {
187				return true
188			}
189		}
190		return false
191	}
192	
193	// isCheckpointRemoteCommitted returns true if the committed .entire/settings.json
194	// at HEAD contains a valid checkpoint_remote configuration. This is the true
195	// discoverability check: entire.io reads from committed project settings, not from
196	// local overrides or uncommitted changes.
197	func isCheckpointRemoteCommitted(ctx context.Context) bool {
198		cmd := exec.CommandContext(ctx, "git", "show", "HEAD:.entire/settings.json")
199		output, err := cmd.Output()
200		if err != nil {
201			return false // file doesn't exist at HEAD
202		}
203		// Parse the committed content and check for checkpoint_remote
204		committed, err := settings.LoadFromBytes(output)
205		if err != nil {
206			return false
207		}
208		return committed.GetCheckpointRemote() != nil
209	}
210	
211	// isCheckpointsVersion2Committed returns true if the committed .entire/settings.json
212	// at HEAD sets checkpoints_version to 2.
213	func isCheckpointsVersion2Committed(ctx context.Context) bool {
214		cmd := exec.CommandContext(ctx, "git", "show", "HEAD:.entire/settings.json")
215		output, err := cmd.Output()
216		if err != nil {
217			return false
218		}
219		committed, err := settings.LoadFromBytes(output)
220		if err != nil {
221			return false
222		}
223		return committed.CheckpointsVersion() == 2
224	}
225	
226	// pushResult describes what happened during a push attempt.
227	type pushResult struct {
228		// upToDate is true when the remote already had all commits (nothing transferred).
229		upToDate bool
230	}
231	
232	// parsePushResult checks git push --porcelain output for ref status flags.
233	// In porcelain mode, each ref gets a tab-delimited status line:
234	//
235	//	<flag>\t<from>:<to>\t<summary>
236	//
237	// where flag '=' means the ref was already up-to-date. This is locale-independent,
238	// unlike the human-readable "Everything up-to-date" message.
239	func parsePushResult(output string) pushResult {
240		for _, line := range strings.Split(output, "\n") {
241			if strings.HasPrefix(line, "=\t") {
242				return pushResult{upToDate: true}
243			}
244		}
245		return pushResult{upToDate: false}
246	}
247	
248	// finishPush stops the progress dots and prints "already up-to-date" or "done"
249	// depending on the push result. Only prints the settings commit hint when new
250	// content was actually pushed.
251	func finishPush(ctx context.Context, stop func(string), result pushResult, target string) {
252		if result.upToDate {
253			stop(" already up-to-date")
254		} else {
255			stop(" done")
256			printSettingsCommitHint(ctx, target)
257		}
258		printCheckpointsV2MigrationHint(ctx)
259	}
260	
261	// tryPushSessionsCommon attempts to push the sessions branch.
262	func tryPushSessionsCommon(ctx context.Context, remote, branchName string) (pushResult, error) {
263		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
264		defer cancel()
265	
266		// Use --no-verify to prevent recursive hook calls.
267		// Use --porcelain for machine-readable, locale-independent output.
268		cmd := CheckpointGitCommand(ctx, remote, "push", "--no-verify", "--porcelain", remote, branchName)
269	
270		output, err := cmd.CombinedOutput()
271		outputStr := string(output)
272		if err != nil {
273			// Check if it's a non-fast-forward error (we can try to recover)
274			if strings.Contains(outputStr, "non-fast-forward") ||
275				strings.Contains(outputStr, "rejected") {
276				return pushResult{}, errors.New("non-fast-forward")
277			}
278			return pushResult{}, fmt.Errorf("push failed: %s", outputStr)
279		}
280	
281		return parsePushResult(outputStr), nil
282	}
283	
284	// fetchAndRebaseSessionsCommon fetches remote sessions and rebases local commits
285	// on top of the remote tip. Since checkpoint shards use unique paths, rebases
286	// always apply cleanly.
287	// The target can be a remote name or a URL.
288	func fetchAndRebaseSessionsCommon(ctx context.Context, target, branchName string) error {
289		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
290		defer cancel()
291	
292		fetchTarget, err := ResolveFetchTarget(ctx, target)
293		if err != nil {
294			return fmt.Errorf("resolve fetch target: %w", err)
295		}
296	
297		// Determine fetch refspec. When the resolved fetch target is a URL, use a
298		// temp ref; when it's still a remote name, use the standard remote-tracking
299		// ref.
300		var fetchedRefName plumbing.ReferenceName
301		var refSpec string
302		usedTempRef := isURL(fetchTarget)
303		if usedTempRef {
304			tmpRef := "refs/entire-fetch-tmp/" + branchName
305			refSpec = fmt.Sprintf("+refs/heads/%s:%s", branchName, tmpRef)
306			fetchedRefName = plumbing.ReferenceName(tmpRef)
307		} else {
308			refSpec = fmt.Sprintf("+refs/heads/%s:refs/remotes/%s/%s", branchName, target, branchName)
309			fetchedRefName = plumbing.NewRemoteReferenceName(target, branchName)
310		}
311	
312		// Use git CLI for fetch (go-git's fetch can be tricky with auth).
313		// Use --filter=blob:none for a partial fetch that downloads only commits
314		// and trees, skipping blobs. The merge only needs the tree structure to
315		// combine entries; blobs are already local or fetched on demand.
316		fetchArgs := AppendFetchFilterArgs(ctx, []string{"fetch", "--no-tags", fetchTarget, refSpec})
317		fetchCmd := CheckpointGitCommand(ctx, fetchTarget, fetchArgs...)
318		if output, err := fetchCmd.CombinedOutput(); err != nil {
319			return fmt.Errorf("fetch failed: %s", output)
320		}
321	
322		repo, err := OpenRepository(ctx)
323		if err != nil {
324			return fmt.Errorf("failed to open git repository: %w", err)
325		}
326	
327		// Reconcile disconnected metadata branches before rebasing.
328		// The fetch above updated the remote-tracking ref, so reconciliation
329		// can compare fresh local vs remote. If disconnected (empty-orphan bug),
330		// this cherry-picks local commits onto remote tip, updating the local ref.
331		// If reconciliation fails, abort — proceeding to rebase on disconnected
332		// branches would silently combine unrelated histories.
333		if reconcileErr := ReconcileDisconnectedMetadataBranch(ctx, repo, fetchedRefName, os.Stderr); reconcileErr != nil {
334			return fmt.Errorf("metadata reconciliation failed: %w", reconcileErr)
335		}
336	
337		// Get local branch (re-read after potential reconciliation update)
338		localRef, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
339		if err != nil {
340			return fmt.Errorf("failed to get local ref: %w", err)
341		}
342	
343		// Get fetched ref (remote-tracking or temp ref, updated by the fetch above)
344		remoteRef, err := repo.Reference(fetchedRefName, true)
345		if err != nil {
346			return fmt.Errorf("failed to get remote ref: %w", err)
347		}
348	
349		// If local is already at or behind remote, fast-forward
350		if localRef.Hash() == remoteRef.Hash() {
351			return nil
352		}
353	
354		// Find merge base
355		repoPath, err := getRepoPath(repo)
356		if err != nil {
357			return fmt.Errorf("failed to get repo path: %w", err)
358		}
359		mergeBase, err := getMergeBase(ctx, repoPath, localRef.Hash().String(), remoteRef.Hash().String())
360		if err != nil {
361			return fmt.Errorf("failed to find merge base: %w", err)
362		}
363	
364		// If local is ancestor of remote (merge base == local), fast-forward to remote
365		if mergeBase == localRef.Hash() {
366			ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
367			if err := repo.Storer.SetReference(ref); err != nil {
368				return fmt.Errorf("failed to fast-forward branch ref: %w", err)
369			}
370			if usedTempRef {
371				_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
372			}
373			return nil
374		}
375	
376		// Collect commits reachable from local but not from remote and cherry-pick
377		// them onto the remote tip. This preserves local-only commits even when the
378		// local metadata branch already contains old merge commits, while avoiding
379		// replaying shared ancestors older than the true merge-base.
380		localCommits, err := collectCommitsSince(ctx, repo, repoPath, localRef.Hash(), remoteRef.Hash())
381		if err != nil {
382			return fmt.Errorf("failed to collect local commits: %w", err)
383		}
384	
385		if len(localCommits) == 0 {
386			// No local-only commits — just point to remote
387			ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
388			if err := repo.Storer.SetReference(ref); err != nil {
389				return fmt.Errorf("failed to update branch ref: %w", err)
390			}
391			if usedTempRef {
392				_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
393			}
394			return nil
395		}
396	
397		newTip, err := cherryPickOnto(ctx, repo, remoteRef.Hash(), localCommits)
398		if err != nil {
399			return fmt.Errorf("failed to rebase local commits onto remote: %w", err)
400		}
401	
402		// Update branch ref
403		newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), newTip)
404		if err := repo.Storer.SetReference(newRef); err != nil {
405			return fmt.Errorf("failed to update branch ref: %w", err)
406		}
407	
408		// Clean up temp ref if we used one (best-effort, not critical if it fails)
409		if usedTempRef {
410			_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
411		}
412	
413		return nil
414	}
415	
416	// getMergeBase returns the merge base hash of two commits, or an error if they
417	// have no common ancestor.
418	func getMergeBase(ctx context.Context, repoPath, hashA, hashB string) (plumbing.Hash, error) {
419		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
420		defer cancel()
421	
422		cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
423		cmd.Dir = repoPath
424		output, err := cmd.Output()
425		if err != nil {
426			return plumbing.ZeroHash, fmt.Errorf("git merge-base failed: %w", err)
427		}
428	
429		return plumbing.NewHash(strings.TrimSpace(string(output))), nil
430	}
431	
432	// collectCommitsSince returns non-merge commits reachable from tip but not from
433	// exclude, ordered oldest-first in topological order.
434	func collectCommitsSince(ctx context.Context, repo *git.Repository, repoPath string, tip, exclude plumbing.Hash) ([]*object.Commit, error) {
435		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
436		defer cancel()
437	
438		// cherryPickOnto computes each commit's delta against its first parent, so
439		// replaying merge commits would incorrectly re-apply changes that arrived via
440		// non-first-parent history. Limit the replay set to non-merge commits.
441		cmd := exec.CommandContext(ctx, "git", "rev-list", "--reverse", "--topo-order", "--no-merges", exclude.String()+".."+tip.String())
442		cmd.Dir = repoPath
443		output, err := cmd.Output()
444		if err != nil {
445			return nil, fmt.Errorf("git rev-list failed: %w", err)
446		}
447	
448		lines := strings.Fields(string(output))
449		if len(lines) > MaxCommitTraversalDepth {
450			return nil, fmt.Errorf("commit chain exceeded %d commits; aborting rebase", MaxCommitTraversalDepth)
451		}
452	
453		commits := make([]*object.Commit, 0, len(lines))
454		for _, line := range lines {
455			hash := plumbing.NewHash(line)
456			commit, commitErr := repo.CommitObject(hash)
457			if commitErr != nil {
458				return nil, fmt.Errorf("failed to get commit %s: %w", hash, commitErr)
459			}
460			if len(commit.ParentHashes) > 1 {
461				continue
462			}
463			commits = append(commits, commit)
464		}
465	
466		return commits, nil
467	}
468	
469	// startProgressDots prints dots to w every second until the returned stop function
470	// is called. The stop function prints the given suffix and a newline.
471	func startProgressDots(w io.Writer) func(suffix string) {
472		done := make(chan struct{})
473		stopped := make(chan struct{})
474		go func() {
475			defer close(stopped)
476			ticker := time.NewTicker(time.Second)
477			defer ticker.Stop()
478			for {
479				select {
480				case <-done:
481					return
482				case <-ticker.C:
483					fmt.Fprint(w, ".")
484				}
485			}
486		}()
487		return func(suffix string) {
488			close(done)
489			<-stopped // Wait for goroutine to finish before writing suffix
490			fmt.Fprintln(w, suffix)
491		}
492	}
493	
494	// isURL returns true if the target looks like a URL rather than a git remote name.
495	func isURL(target string) bool {
496		return strings.Contains(target, "://") || strings.Contains(target, "@")
497	}
498	
499	// createMergeCommitCommon creates a merge commit with multiple parents.
500	func createMergeCommitCommon(ctx context.Context, repo *git.Repository, treeHash plumbing.Hash, parents []plumbing.Hash, message string) (plumbing.Hash, error) {
501		authorName, authorEmail := GetGitAuthorFromRepo(repo)
502		now := time.Now()
503		sig := object.Signature{
504			Name:  authorName,
505			Email: authorEmail,
506			When:  now,
507		}
508	
509		commit := &object.Commit{
510			TreeHash:     treeHash,
511			ParentHashes: parents,
512			Author:       sig,
513			Committer:    sig,
514			Message:      message,
515		}
516	
517		checkpoint.SignCommitBestEffort(ctx, commit)
518	
519		obj := repo.Storer.NewEncodedObject()
520		if err := commit.Encode(obj); err != nil {
521			return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
522		}
523	
524		hash, err := repo.Storer.SetEncodedObject(obj)
525		if err != nil {
526			return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
527		}
528	
529		return hash, nil
530	}
